/* port: zdb::IntersectStruct::GetMaxRegionShift 0x2553c0 (static, emitted in this unit; not
 * declared in the port): the index of the highest set region bit (0 for none) */
static u32 MaxRegionShift(u32 regions)
{
	if (regions == 0)
		return 0;

	u32 shift = (u32)-1;

	while (regions != 0)
	{
		regions >>= 1;
		shift++;
	}

	return shift;
}

